#!/usr/bin/env node
// Regenerates what is derived from /shared, so the look and the sample data have one
// source.
//
//   node scripts/sync-shared.mjs          write the generated files
//   node scripts/sync-shared.mjs --check  exit 1 if any generated file is stale (CI)
//
// Inputs:  shared/design/tokens.json, shared/fonts/*, shared/logo.png, shared/data/seed.json
// Outputs: packages/ui/src/theme.css   Tailwind @theme + @font-face from the tokens
//          packages/ui/src/assets/     fonts and logo
//          packages/core/src/seed.json the sample data, copied so the kernel package is self-contained

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const stale = [];

function emit(rel, content) {
  const path = join(root, rel);
  const next = Buffer.isBuffer(content) ? content : Buffer.from(content);
  const prev = existsSync(path) ? readFileSync(path) : null;

  if (prev && prev.equals(next)) return;

  if (check) {
    stale.push(rel);

    return;
  }

  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, next);
  console.log('wrote', rel);
}

const tokens = JSON.parse(readFileSync(join(root, 'shared/design/tokens.json'), 'utf8'));
const kebab = (s) => s.replace(/([a-z])([A-Z0-9])/g, '$1-$2').toLowerCase();

// "#rrggbbaa" -> "rgb(r g b / a)"; "#rrggbb" stays.
function color(hex) {
  const h = hex.replace('#', '');

  if (h.length !== 8) return hex;
  const n = (i) => parseInt(h.slice(i, i + 2), 16);

  return `rgb(${n(0)} ${n(2)} ${n(4)} / ${(n(6) / 255).toFixed(3)})`;
}

const faces = [
  ['Orbitron', 'Orbitron.ttf', '400 900'],
  ['Poppins', 'Poppins-Regular.ttf', '400'],
  ['Poppins', 'Poppins-Medium.ttf', '500'],
  ['Poppins', 'Poppins-SemiBold.ttf', '600'],
  ['Poppins', 'Poppins-Bold.ttf', '700'],
];

const css = `/* Generated by scripts/sync-shared.mjs from shared/design/tokens.json. Do not edit by hand. */
${faces.map(([family, file, weight]) => `@font-face {
  font-family: "${family}";
  src: url("./assets/fonts/${file}") format("truetype");
  font-weight: ${weight};
  font-style: normal;
  font-display: swap;
}`).join('\n')}

@theme {
${Object.entries(tokens.color).map(([k, v]) => `  --color-${kebab(k)}: ${color(v)};`).join('\n')}

  --font-display: "${tokens.font.display}", ui-sans-serif, system-ui, sans-serif;
  --font-body: "${tokens.font.body}", "Segoe UI", ui-sans-serif, system-ui, sans-serif;

${Object.entries(tokens.radius).map(([k, v]) => `  --radius-${kebab(k)}: ${v}px;`).join('\n')}

${Object.entries(tokens.layout).map(([k, v]) => `  --size-${kebab(k)}: ${v}px;`).join('\n')}
}
`;

emit('packages/ui/src/theme.css', css);

for (const f of readdirSync(join(root, 'shared/fonts'))) {
  emit(`packages/ui/src/assets/fonts/${f}`, readFileSync(join(root, 'shared/fonts', f)));
}

emit('packages/ui/src/assets/logo.png', readFileSync(join(root, 'shared/logo.png')));

emit('packages/core/src/seed.json', readFileSync(join(root, 'shared/data/seed.json')));

if (check && stale.length) {
  console.error('Generated files are out of date. Run `npm run sync` and commit:\n  ' + stale.join('\n  '));
  process.exit(1);
}

if (check) console.log('Generated files are up to date.');
